import 'package:process/process.dart';

Future<ProcessResult> run(ProcessManager processManager, String cmd) =>
    processManager.run(['kubectl', 'exec', 'p', '--', 'sh', '-c', cmd]);

import 'package:process/process.dart';

Future<ProcessResult> run(ProcessManager processManager, String path) =>
    processManager.run(['git', 'log', '--', path]);

Future<ProcessResult> run(String v) {
  final base = ['--json'];
  base.add(v);
  return Process.run('git', ['log', ...base]);
}

class Tool {
  final base = ['--json'];

  void push(String v) => base.add(v);

  Future<ProcessResult> run() => Process.run('git', ['log', ...base]);
}

Future<ProcessResult> run(String v) {
  final args = ['log'];
  args.add(v);
  return Process.run('git', args);
}

Future<ProcessResult> run(String v) {
  final base = ['log'];
  base.insert(0, v);
  return Process.run('git', base);
}

Future<ProcessResult> run(String v) {
  final args = ['log', 'x'];
  args[1] = v;
  return Process.run('git', args);
}

Future<ProcessResult> run(List<String> v) {
  final args = ['log'];
  args.addAll(v);
  return Process.run('git', args);
}

Future<ProcessResult> run() {
  final args = ['log', '--oneline'];
  return Process.run('git', args);
}

Future<ProcessResult> run(String e, String v) {
  var exe = 'git';
  exe = e;
  return Process.run(exe, ['--message=$v']);
}

Future<ProcessResult> run(String e, String v) {
  String exe = 'git';
  exe = e;
  return Process.run(exe, ['--message=$v']);
}

class Tool {
  String exe = 'git';

  void use(String e) => exe = e;

  Future<ProcessResult> run(String v) => Process.run(exe, ['--message=$v']);
}

Future<ProcessResult> run(String v) {
  var exe = 'git';
  return Process.run(exe, ['--message=$v']);
}

void run(List<String> vs) {
  vs.forEach((v) {
    Process.run('git', ['log', v]);
  });
}
